// Caller keeps only the rows where n >= min_docs. GQ cannot compare an aggregate to a per-row property, so this query returns both values. It covers collections with at least one document.
query collection_doc_counts() {
    match {
        $c: Collection
        $d: Doc
        $d in $c
    }
    return { $c.slug, $c.min_docs, count($d) as n }
}
