// Caller adds these slugs to the results of the first query. These are empty collections, which the first query cannot see, and they qualify because min_docs <= 0.
query empty_collections_with_no_minimum() {
    match {
        $c: Collection
        $c.min_docs <= 0
        not { $_ in $c }
    }
    return { $c.slug }
}
